{"description":"Find valid annealing length pairs","cmd":"python3 - <<'PY'
import subprocess

def tm(seq):
    r=subprocess.run(['oligotm','-tp','1','-sc','1','-mv','50','-dv','2','-n','0.8','-d','500',seq],capture_output=True,text=True)
    return float(r.stdout.strip())

recs={}; cur=None
for line in open('sequences.fasta'):
    line=line.strip()
    if line.startswith('>'): cur=line[1:]; recs[cur]=''
    else: recs[cur]+=line
si=recs['input']
p=215
# precompute Tm for upstream lengths 15-45 and downstream lengths 15-45
up_tm={}; dn_tm={}
for L in range(15,46):
    up_tm[L]=tm(si[p-L:p])
    dn_tm[L]=tm(si[p:p+L])
valid=[]
for uL, uT in up_tm.items():
    for dL, dT in dn_tm.items():
        if 58 <= uT <= 72 and 58 <= dT <= 72 and abs(uT-dT)<=5:
            valid.append((abs(uT-dT), uL, uT, dL, dT))
valid.sort()
print('num valid', len(valid))
for diff, uL, uT, dL, dT in valid[:30]:
    print(f'uplen={uL} (Tm={uT:.2f}) dnlen={dL} (Tm={dT:.2f}) diff={diff:.2f}')
PY"}

