def rc(s): return s.translate(str.maketrans('ACGT','TGCA'))[::-1]
for s in ['ATGC','AATTCCGG','CAGGGTTAAGG','TTGTTTAACTTT']:
    print(s, tm(s), rc(s), tm(rc(s)))
